#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

#define MAX_ELEM 10
static int parent[MAX_ELEM];
static int rank_[MAX_ELEM];

static int find_set(int x) {
    if (parent[x] != x)
        parent[x] = find_set(parent[x]);
    return parent[x];
}

static void union_set(int x, int y) {
    int rx = find_set(x);
    int ry = find_set(y);
    if (rx == ry) return;
    if (rank_[rx] < rank_[ry])
        parent[rx] = ry;
    else {
        parent[ry] = rx;
        if (rank_[rx] == rank_[ry])
            rank_[rx]++;
    }
}

static int parse_index(const char *s) {
    char *end;
    long v;
    errno = 0;
    v = strtol(s, &end, 10);
    if (errno != 0 || *end != '\0') return -1;
    if (v < 0 || v >= MAX_ELEM) return -1;
    return (int)v;
}

int main(int argc, char **argv) {
    for (int i = 0; i < MAX_ELEM; ++i) { parent[i] = i; rank_[i] = 0; }
    if (argc < 2) { puts("NOOP"); return 0; }
    int idx = 1;
    while (idx < argc) {
        const char *cmd = argv[idx];
        if (cmd[0] == 'U') {
            if (idx + 2 >= argc) { puts("INVALID"); break; }
            int a = parse_index(argv[idx+1]);
            int b = parse_index(argv[idx+2]);
            if (a < 0 || b < 0) puts("INVALID");
            else { printf("UNION %d %d\n", a, b); union_set(a,b); }
            idx += 3;
        } else if (cmd[0] == 'F') {
            if (idx + 1 >= argc) { puts("INVALID"); break; }
            int a = parse_index(argv[idx+1]);
            if (a < 0) puts("INVALID");
            else { int r = find_set(a); printf("FIND %d=%d\n", a, r); }
            idx += 2;
        } else if (cmd[0] == 'C') {
            if (idx + 2 >= argc) { puts("INVALID"); break; }
            int a = parse_index(argv[idx+1]);
            int b = parse_index(argv[idx+2]);
            if (a < 0 || b < 0) puts("INVALID");
            else { puts(find_set(a) == find_set(b) ? "YES" : "NO"); }
            idx += 3;
        } else {
            puts("INVALID");
            break;
        }
    }
    return 0;
}
